  2502  mf_check__(const struct mf_subfield *sf, const struct match *match,
  2503             const char *type)
  2504  {
  2505      if (!sf->field) {
  2506          VLOG_WARN_RL(&rl, "unknown %s field", type);
  2507          return OFPERR_OFPBAC_BAD_SET_TYPE;
  2508      } else if (!sf->n_bits) {
  2509          VLOG_WARN_RL(&rl, "zero bit %s field %s", type, sf->field->name);
  2510          return OFPERR_OFPBAC_BAD_SET_LEN;
  2511      } else if (sf->ofs >= sf->field->n_bits) {
  2512          VLOG_WARN_RL(&rl, "bit offset %d exceeds %d-bit width of %s field %s",
  2513                       sf->ofs, sf->field->n_bits, type, sf->field->name);
  2514          return OFPERR_OFPBAC_BAD_SET_LEN;
  2515      } else if (sf->ofs + sf->n_bits > sf->field->n_bits) {
  2516          VLOG_WARN_RL(&rl, "bit offset %d and width %d exceeds %d-bit width "
  2517                       "of %s field %s", sf->ofs, sf->n_bits,
  2518                       sf->field->n_bits, type, sf->field->name);
  2519          return OFPERR_OFPBAC_BAD_SET_LEN;
  2520      } else if (match && !mf_are_match_prereqs_ok(sf->field, match)) {
  2521          VLOG_WARN_RL(&rl, "%s field %s lacks correct prerequisites",
  2522                       type, sf->field->name);
  2523          return OFPERR_OFPBAC_MATCH_INCONSISTENT;
  2524      } else {
  2525          return 0;
  2526      }
  2527  }
